158	fn sign_extend_12(value: u16) -> i32 {
159	    let v = (value & 0x0FFF) as i32;
160	    if v & 0x0800 != 0 { v - 0x1000 } else { v }
161	}
162	
163	fn byte_of_u16(reg: u16, idx: u8) -> u8 {
164	    // Even index = high byte; odd = low byte. 16-bit reads on TMP101
165	    // continue past the second byte by re-reading from the start.
166	    if idx.is_multiple_of(2) {
167	        (reg >> 8) as u8
168	    } else {
169	        (reg & 0xFF) as u8
170	    }
171	}
172	
173	fn patch_u16(reg: u16, idx: u8, byte: u8) -> u16 {
174	    if idx == 1 {
175	        (reg & 0x00FF) | ((byte as u16) << 8)
176	    } else if idx == 2 {
177	        (reg & 0xFF00) | (byte as u16)
178	    } else {
179	        reg
180	    }
181	}
